import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused kernel for residual addition and multiplication
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_ops_kernel(const float* x_linear, const float* y, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        // Instance norm effectively zeros input due to 1x1 spatial dim
        // Followed by: (0 + y) * y
        out[idx] = y[idx] * y[idx];
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor x_linear, torch::Tensor y) {
    auto out = torch::empty_like(y);
    int size = y.numel();

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(x_linear.data_ptr<float>(), 
                                               y.data_ptr<float>(), 
                                               out.data_ptr<float>(), 
                                               size);

    return out;
}
"""

fused_ops_cpp_source = "torch::Tensor fused_ops_cuda(torch::Tensor x_linear, torch::Tensor y);"

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_ops_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.bmm = nn.Linear(in_features, out_features)
        self.fused_ops = fused_ops

    def forward(self, x, y):
        x_linear = self.bmm(x)
        return self.fused_ops.fused_ops_cuda(x_linear, y)
